/**
 * Application entry point. Builds the DI graph lazily, starts observing
 * connectivity so a reconnect immediately triggers a drain (current state
 * first, then backlog), and schedules a periodic safety-net sync (docs/spec/06,
 * 79).
 */
class TripPulseApp : Application() {

    val graph: AppGraph by lazy { AppGraph(this) }

    override fun onCreate() {
        super.onCreate()
        com.trippulse.app.core.CrashLog.install(this)
        com.trippulse.app.ui.SharedPlaceInbox.attach(this)

        // MapLibre (vector maps, OpenFreeMap tiles): initialised once, up front,
        // so the first map on screen doesn't pay the start-up cost. Its tile
        // cache lives in app-private storage and needs no permission.
        com.trippulse.app.ui.map.ensureMapLibre(this)

        graph.notifier.ensureChannels()

        // Server push: lets a followed journey's updates wake this phone even
        // while Koode is closed. A no-op in builds without Firebase values.
        graph.push.init()

        // Reconnect -> drain. The journey continues locally regardless; this only
        // affects when the server receives events.
        graph.appScope.launch {
            graph.connectivity.changes().collectLatest { online ->
                if (online) {
                    // An approval made offline reaches the followers now.
                    graph.publisher.resume()
                    graph.tollPlazas.refresh()
                    val trip = graph.db.tripDao().activeTrip() ?: return@collectLatest
                    graph.sync.drain(trip)
                }
            }
        }

        // Resume viewer alerting for any trips this phone is still following.
        graph.appScope.launch {
            val following = try { graph.db.viewerDao().activeList() } catch (_: Exception) { emptyList() }
            if (following.isNotEmpty() && graph.cloud.isAvailable()) {
                com.trippulse.app.service.TripFollowService.start(this@TripPulseApp)
            }
        }

        scheduleSyncRetry()
        // Runs regardless of network: it exists for the cases where the network
        // (or the service, or the traveller's memory) is the thing that failed.
        com.trippulse.app.service.JourneyKeeperWorker.schedule(this)
    }

    private fun scheduleSyncRetry() {
        val req = PeriodicWorkRequestBuilder<SyncRetryWorker>(15, TimeUnit.MINUTES)
            .setConstraints(
                Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()
            )

/**
 * The toll plazas Koode counts crossings at (OpenStreetMap toll booths,
 * © OpenStreetMap contributors, ODbL).
 *
 * Offline-first: the list downloaded last, else the copy bundled into the
 * APK at release time, else none (manual "Toll crossed" still works). It is
 * refreshed from the Koode backend at most every few days, and only
 * re-downloaded when the backend has a newer version.
 */
class TollPlazaRepository(
    private val context: Context,
    private val cloud: TripCloud,
    private val scope: CoroutineScope
) {
    private val file = File(context.filesDir, "toll_plazas.csv")
    private val prefs = context.getSharedPreferences("tp_toll_plazas", Context.MODE_PRIVATE)
    private val refreshLock = Mutex()

    @Volatile private var cached: TollPlazas.Index? = null

    /** The current plaza index; loaded on first use. */
    fun index(): TollPlazas.Index = cached ?: synchronized(this) {
        cached ?: load().also { cached = it }
    }

    /** Checks the backend for a newer list, at most every [CHECK_EVERY_MS]. */
    fun refresh(force: Boolean = false) {
        scope.launch {
            refreshLock.withLock {
                val now = System.currentTimeMillis()
                if (!force && now - prefs.getLong(KEY_CHECKED, 0L) < CHECK_EVERY_MS) return@withLock
                val (version, body) = cloud.tollPlazas(currentVersion()) ?: return@withLock
                prefs.edit().putLong(KEY_CHECKED, now).apply()
                if (body.isNullOrBlank()) return@withLock
                val plazas = TollPlazas.decode(body)
                if (plazas.size < MIN_PLAUSIBLE) return@withLock  // a broken list never replaces a good one
                runCatching {
                    val tmp = File(file.parentFile, "${file.name}.tmp")
                    tmp.writeText(body)
                    if (!tmp.renameTo(file)) { file.delete(); tmp.renameTo(file) }
                    prefs.edit().putLong(KEY_VERSION, version).apply()
                    cached = TollPlazas.Index(plazas)
                    Log.i(TAG, "Toll plazas updated: ${plazas.size} (version $version)")
                }.onFailure { Log.w(TAG, "Could not store toll plazas", it) }
            }
        }
    }

