async function loadJSON(path) {
  if (_cache[path]) return _cache[path];
  try {
    const r = await fetch(path + '?v=' + Date.now());
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const data = await r.json();
    _cache[path] = data;
    return data;
  } catch (e) {
    console.warn('loadJSON failed:', path, e);
