function isToday(dateStr) {
  const today = new Date();
  const d = new Date(dateStr + 'T00:00:00');
  return d.toDateString() === today.toDateString();
}
function isPast(dateStr) {
  const d = new Date(dateStr + 'T23:59:59');
  return d < new Date();
