        return json.dumps(engine().callers(name), indent=2)

    @app.tool()
    def impact_analysis(name: str, max_depth: int = 4) -> str:
        """Transitive dependents of a symbol — what could break if it
        changes (via call, inheritance, and import edges)."""
        return json.dumps(engine().impact(name, max_depth=max_depth), indent=2)

    @app.tool()
    def file_outline(file_path: str) -> str:
        """Symbol outline (classes/functions with lines) for a file."""
        return json.dumps(engine().outline(file_path), indent=2)

    @app.tool()
    def reindex(full: bool = False) -> str:
        """Refresh the index after code changes (incremental by default)."""
        stats = Indexer(root, IndexConfig()).build(full=full)
        state.pop("e", None)
        return (f"indexed {stats.files_indexed} files, "
                f"{stats.chunks} chunks, {stats.symbols} symbols")

    @app.tool()
    def index_stats() -> str:
        """Index size, languages, and embedder info."""
        return json.dumps(engine().stats(), indent=2)

    app.run()

@dataclass
class Chunk:
    """A retrieval unit produced by structure-aware chunking.

    Chunks follow the cAST principle: boundaries respect syntactic
    structure (function/class/module blocks), small siblings are merged,
    oversized nodes are split recursively.
    """

    chunk_id: str
    file_path: str
    language: str
    start_line: int  # 1-based, inclusive
    end_line: int  # 1-based, inclusive
    text: str
    kind: str = "block"  # module | class | function | method | block
    symbol: Optional[str] = None  # qualified name, e.g. "pkg.mod.Class.method"
    docstring: Optional[str] = None

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Chunk":
        return cls(**d)


@dataclass
class Symbol:
    """A named definition extracted from source code."""

    name: str
    qualified_name: str
    kind: str  # class | function | method
    file_path: str
    start_line: int
    end_line: int
    signature: str = ""
    docstring: str = ""
    bases: list[str] = field(default_factory=list)  # for classes
    calls: list[str] = field(default_factory=list)  # callee names (best effort)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Symbol":
        return cls(**d)


@dataclass
class SearchResult:
    """A fused search hit with provenance and graph context."""

    chunk: Chunk
    score: float
    sources: list[str] = field(default_factory=list)  # e.g. ["bm25", "dense"]
    related: list[dict[str, Any]] = field(default_factory=list)  # graph neighbors
